)
values
  (
    'nutrition.vegetable_carbohydrate_equivalence',
    'nutrition',
    'method_engine_v1',
    'Equivalência de legumes em carboidrato',
    'Template versionado da equivalência confirmada entre doses de legumes e doses de carboidrato.',
    'system',
    null
  ),
  (
    'workflow.anamnesis_clarification_reminder',
    'workflow',
    'scalar_parameter_v1',
    'Intervalo do lembrete de esclarecimento',
    'Template versionado do intervalo confirmado para considerar um lembrete de esclarecimento devido.',
    'system',
